// Per-group analytics. God mode only, same moderator gate as event Analytics.
// Counts are this group's club events: page views and app RSVPs.
// Meetup's group size is not loaded and not shown.
import { useCallback, useEffect, useState } from 'react';
import { RefreshControl, Text, View } from 'react-native';
import { Redirect, router, Stack, useLocalSearchParams } from 'expo-router';
import { AnalyticsFunnel, AnalyticsViewLog, formatCount, Stat } from '../../../components/stat';
import { ErrorText, ListRow, ListView, Page, PageHeader, SectionCard, styles } from '../../../components/ui';
import { useCanModerate } from '../../../components/mod';
import { getGroupAnalytics, viewerCountSentence, type GroupAnalytics } from '../../../lib/analytics';
import { getGroup } from '../../../lib/groups';
import { fmtWhen } from '../../../lib/format';
import { colors, fs } from '../../../lib/theme';

export default function GroupAnalyticsPage() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { ready, ok } = useCanModerate();
  const [title, setTitle] = useState('Group');
  const [city, setCity] = useState<string | null>(null);
  const [data, setData] = useState<GroupAnalytics | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    if (!id) return;
    setBusy(true);
    setErr(null);
    const group = getGroup(id).then((row) => {
      if (row) {
        setTitle(row.name);
        setCity(row.locality);
      }
    }).catch(() => {});
    const stats = getGroupAnalytics(id).then(setData).catch((e: { message?: string }) => {
      setErr(e.message ?? 'Couldn’t load group analytics.');
      setData(null);
    });
    await Promise.all([group, stats]);
    setBusy(false);
  }, [id]);

  useEffect(() => { if (ok) load(); }, [ok, load]);

  if (!ready) return <View style={{ flex: 1, backgroundColor: colors.paper }} />;
  if (!ok || !id) return <Redirect href={id ? `/groups/${id}` : '/groups'} />;

  const viewers = data?.viewers ?? 0;
  return (
    <Page refreshControl={<RefreshControl refreshing={busy} onRefresh={load} />}>
      <Stack.Screen options={{ title: 'Analytics' }} />
      <Text onPress={() => router.navigate(`/groups/${id}`)} accessibilityRole="link" style={[styles.link, { fontSize: fs(13) }]}>Back to group</Text>
      <PageHeader icon="bar-chart" eyebrow="Analytics" title={title} subtitle={city ?? 'This group'} />
      <ErrorText>{err}</ErrorText>
      {busy && !data ? <Text style={styles.muted}>Loading…</Text> : null}
      {data ? (
        <>
          <SectionCard title="Who viewed these events">
            <Text style={[styles.muted, { fontSize: fs(13), marginBottom: 12 }]}>
              {viewerCountSentence(viewers, data.views, 'on this group’s event pages. Meetup’s group size is not shown.')}
            </Text>
            <Stat label="App users" value={viewers} note="Signed-in viewers" />
          </SectionCard>
          <SectionCard title="Funnel">
            <AnalyticsFunnel anonymous={data.funnel.anonymousViews} authenticated={data.funnel.authenticatedViews} rsvps={data.funnel.rsvps}
              anonymousNote="Public event pages" authenticatedNote="App users" rsvpNote="App attend" />
          </SectionCard>
          <ListView title="Events" note="App views and RSVPs. Not a Meetup member list." count={data.eventRows.length}
            empty={<Text style={[styles.muted, { padding: 16 }]}>No events in this group.</Text>}>
            {data.eventRows.map((row) => (
              <ListRow key={row.id} onPress={() => router.push(`/events/${row.id}/analytics`)} accessibilityLabel={`Analytics for ${row.title}`}>
                <View style={{ flex: 1, minWidth: 0, gap: 2 }}>
                  <Text style={styles.rowPrimary} numberOfLines={1}>{row.title}</Text>
                  <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>
                    {row.startsAt ? fmtWhen(row.startsAt) : '—'} · {formatCount(row.views)} {row.views === 1 ? 'view' : 'views'} · {formatCount(row.rsvps)} {row.rsvps === 1 ? 'RSVP' : 'RSVPs'}
                  </Text>
                </View>
              </ListRow>
            ))}
          </ListView>
          <SectionCard title="Views">
            <AnalyticsViewLog rows={data.log} showEventTitle />
          </SectionCard>
        </>
      ) : null}
    </Page>
  );
}
